from lib import *
S = SS('f170')
R = J('f170'); ls = R['lost']; k = list(ls); dc = R['dict']; cn = R['conn']
w0, w1, w2 = ls[k[0]], ls[k[1]], ls[k[2]]
steps = [
    step(f"读-改-写的计数器,ab 发 2000 个 POST、32 并发,gunicorn gthread 1 个 worker × 32 线程:读和写之间没有任何让出(窗口 0)时,计数 {w0[0]} / 2000,一次更新都没丢——压测一点问题都没发现;读和写之间有 0.0001 秒的窗口(比如中间调了一次数据库或别的接口),计数 {w1[0]} / 2000,丢了 {w1[1]} 次({w1[1] / 20:.1f}%);窗口 0.001 秒,计数 {w2[0]} / 2000,丢了 {w2[1]} 次({w2[1] / 20:.1f}%);用 threading.Lock 保护后是 {R['safe']} / 2000。竞争条件能不能被压测碰到,取决于读和写之间有多长的窗口——窗口很短时压测通过不代表代码是安全的。", b=bars([['窗口 0', w0[1], f'丢 {w0[1]}'], ['窗口 0.0001 秒', w1[1], f'丢 {w1[1]}'], ['窗口 0.001 秒', w2[1], f'丢 {w2[1]}']], 2000, mark=[1, 2], done=[0]), t=tl(S(1)), done=lidx(S(1), '窗口 0(', '加锁'), mark=lidx(S(1), '窗口 0.0001', '窗口 0.001'), kv=KV([['窗口 0', '压测里没有丢失'], ['窗口 0.0001 秒', f'丢了 {w1[1] / 20:.0f}%'], ['窗口 0.001 秒', f'丢了 {w2[1] / 20:.0f}%']], ['窗口 0.0001 秒'])),
    step(f"遍历全局字典时另一个请求在修改它:字典有 30 万项,/sum 遍历它求和,同时有 /mutate 在往里加删一个 key。/sum 3000 个请求里,并发 1 时有 {dc['1'][0]} 个、并发 32 时有 {dc['32'][0]} 个返回 500,日志里是 RuntimeError「dictionary changed size during iteration」({dc['1'][1]}、{dc['32'][1]} 次)。遍历很长的共享容器,同时有别处修改,就会出这个错——哪怕 /sum 自己一次只有一个请求(并发 1),修改它的是另一类请求。要遍历前先拷贝(list(d.items()))或加锁。", t=tl(S(2)), done=lidx(S(2), '/sum 并发'), kv=KV([['遍历 + 修改', 'dictionary changed size during iteration'], ['对策', '遍历前拷贝,或加锁']], ['遍历 + 修改'])),
    step(f"被所有线程共用的 sqlite3 连接(check_same_thread=False 只是关掉了线程检查):3000 个请求、32 并发,共用一个连接的 /shared-conn 非 2xx {cn['共用一个连接'][0]} 个,每个请求自己的连接的 /own-conn 也是 {cn['每个请求自己的连接'][0]} 个,日志里没有异常。也就是说:这个例子里压测没有发现问题——sqlite3 模块自己对连接做了串行化,不等于所有「共享的连接」都安全(别的驱动、事务状态与游标的共享就未必)。不能把「没出错」当作「线程安全」;用连接池给每个请求独立的连接才是通用的做法(第 91 篇)。", t=tl(S(3)), done=lidx(S(3), '共用一个连接', '每个请求自己的连接'), kv=KV([['sqlite3 共用连接', '本次压测没有出错'], ['结论', '没出错 ≠ 线程安全']], ['结论'])),
]
A = mkartf('f170', 170, 'Flask,压测,全局状态,竞争条件,线程安全,真实验证,动画演示',
    f'用 ab 压测暴露全局状态问题:读和写之间窗口为 0 时计数一点没丢、窗口 0.0001 秒丢 {w1[1] / 20:.0f}%、窗口 0.001 秒丢 {w2[1] / 20:.0f}%;遍历 30 万项的全局字典时被并发修改会让 {dc["32"][0]} 个请求 500;共用的 sqlite3 连接这次压测没出错,说明压测过关不等于线程安全。',
    '压测能不能发现全局状态的并发问题?什么样的竞争压测碰得到、碰不到?为什么「压测没出错」不等于线程安全?这篇用 ab 与真实的 gunicorn 线程,把三种全局状态问题各压一遍。',
    [(f'{w0[1]} / {w1[1] / 20:.0f}% / {w2[1] / 20:.0f}%', '读写间没有窗口、0.0001 秒窗口、0.001 秒窗口时压测里丢失的更新'), (f'{dc["32"][0]} / 3000', '遍历全局字典同时被修改时返回 500 的请求数(并发 32)'), ('没出错 ≠ 安全', '共用 sqlite3 连接的压测没发现问题,但不能据此认为线程安全')],
    [('计数器的窗口', '<p>上一篇:<a href="flask-large-file-response-performance.html">大文件响应性能</a>;下一篇:<a href="flask-dev-server-vs-production.html">Flask Development Server 与生产服务器</a>(第 171 篇起是部署部分)。</p><p>第 143、145 篇从线程与进程的角度讲过全局变量,这一篇用压测的角度看它。第一次运行时我用 time.sleep(0) 当「读写之间的窗口」,一点竞争也没压出来,才发现窗口大小这个变量,于是加了几档窗口。</p>'), ('遍历时被修改的全局字典', None), ('共用的数据库连接', None)],
    steps, [ENV_F + '。gunicorn gthread worker、ApacheBench', '没有验证:多进程下全局变量的不一致(第 145 篇)、其它数据库驱动共用连接的行为、requests.Session 等共享客户端对象的线程安全、asyncio 下的类似问题、线程安全检测工具(如 ThreadSanitizer 的 Python 支持)'], '压测下的全局状态问题')
